pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Phishable c;

    function setUp() public {
        __Sink __s = new __Sink();
        c = new Phishable(address(this));
    }

    function _run(address caller, address owner) internal {
        vm.assume(true);
        bool reverted;
        try c.withdrawAll(caller) { reverted = false; } catch { reverted = true; }
        assertTrue(!(caller == owner) || !reverted);
    }

    function testFuzz_run(address caller, address owner) public {
        _run(caller, owner);
    }

    receive() external payable {}
}

contract __Sink {
    fallback() external payable { require(msg.value == 0); }
    receive() external payable { require(msg.value == 0); }
}

